macro_rules! deps {
    () => {
        HashMap!();
        DefaultHashBuilder!();
    };
}

macro_rules! HashSet {
    () => {
        deps!();
        # [doc = " A hash set implemented as a `HashMap` where the value is `()`."] # [doc = ""] # [doc = " As with the [`HashMap`] type, a `HashSet` requires that the elements"] # [doc = " implement the [`Eq`] and [`Hash`] traits. This can frequently be achieved by"] # [doc = " using `#[derive(PartialEq, Eq, Hash)]`. If you implement these yourself,"] # [doc = " it is important that the following property holds:"] # [doc = ""] # [doc = " ```text"] # [doc = " k1 == k2 -> hash(k1) == hash(k2)"] # [doc = " ```"] # [doc = ""] # [doc = " In other words, if two keys are equal, their hashes must be equal."] # [doc = ""] # [doc = ""] # [doc = " It is a logic error for an item to be modified in such a way that the"] # [doc = " item's hash, as determined by the [`Hash`] trait, or its equality, as"] # [doc = " determined by the [`Eq`] trait, changes while it is in the set. This is"] # [doc = " normally only possible through [`Cell`], [`RefCell`], global state, I/O, or"] # [doc = " unsafe code."] # [doc = ""] # [doc = " It is also a logic error for the [`Hash`] implementation of a key to panic."] # [doc = " This is generally only possible if the trait is implemented manually. If a"] # [doc = " panic does occur then the contents of the `HashSet` may become corrupted and"] # [doc = " some items may be dropped from the table."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use hashbrown::HashSet;"] # [doc = " // Type inference lets us omit an explicit type signature (which"] # [doc = " // would be `HashSet<String>` in this example)."] # [doc = " let mut books = HashSet::new();"] # [doc = ""] # [doc = " // Add some books."] # [doc = " books.insert(\"A Dance With Dragons\".to_string());"] # [doc = " books.insert(\"To Kill a Mockingbird\".to_string());"] # [doc = " books.insert(\"The Odyssey\".to_string());"] # [doc = " books.insert(\"The Great Gatsby\".to_string());"] # [doc = ""] # [doc = " // Check for a specific one."] # [doc = " if !books.contains(\"The Winds of Winter\") {"] # [doc = "     println!(\"We have {} books, but The Winds of Winter ain't one.\","] # [doc = "              books.len());"] # [doc = " }"] # [doc = ""] # [doc = " // Remove a book."] # [doc = " books.remove(\"The Odyssey\");"] # [doc = ""] # [doc = " // Iterate over everything."] # [doc = " for book in &books {"] # [doc = "     println!(\"{}\", book);"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " The easiest way to use `HashSet` with a custom type is to derive"] # [doc = " [`Eq`] and [`Hash`]. We must also derive [`PartialEq`]. This will in the"] # [doc = " future be implied by [`Eq`]."] # [doc = ""] # [doc = " ```"] # [doc = " use hashbrown::HashSet;"] # [doc = " #[derive(Hash, Eq, PartialEq, Debug)]"] # [doc = " struct Viking {"] # [doc = "     name: String,"] # [doc = "     power: usize,"] # [doc = " }"] # [doc = ""] # [doc = " let mut vikings = HashSet::new();"] # [doc = ""] # [doc = " vikings.insert(Viking { name: \"Einar\".to_string(), power: 9 });"] # [doc = " vikings.insert(Viking { name: \"Einar\".to_string(), power: 9 });"] # [doc = " vikings.insert(Viking { name: \"Olaf\".to_string(), power: 4 });"] # [doc = " vikings.insert(Viking { name: \"Harald\".to_string(), power: 8 });"] # [doc = ""] # [doc = " // Use derived implementation to print the vikings."] # [doc = " for x in &vikings {"] # [doc = "     println!(\"{:?}\", x);"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " A `HashSet` with fixed list of elements can be initialized from an array:"] # [doc = ""] # [doc = " ```"] # [doc = " use hashbrown::HashSet;"] # [doc = ""] # [doc = " let viking_names: HashSet<&'static str> ="] # [doc = "     [ \"Einar\", \"Olaf\", \"Harald\" ].into_iter().collect();"] # [doc = " // use the values stored in the set"] # [doc = " ```"] # [doc = ""] # [doc = " [`Cell`]: https://doc.rust-lang.org/std/cell/struct.Cell.html"] # [doc = " [`Eq`]: https://doc.rust-lang.org/std/cmp/trait.Eq.html"] # [doc = " [`Hash`]: https://doc.rust-lang.org/std/hash/trait.Hash.html"] # [doc = " [`HashMap`]: struct.HashMap.html"] # [doc = " [`PartialEq`]: https://doc.rust-lang.org/std/cmp/trait.PartialEq.html"] # [doc = " [`RefCell`]: https://doc.rust-lang.org/std/cell/struct.RefCell.html"] pub struct HashSet < T , S = DefaultHashBuilder , A : Allocator = Global > { pub (crate) map : HashMap < T , () , S , A > , }
    };
}

HashSet!()